// mtp_startup.hpp - the µOS++ start-up a test carries on the boards whose
// tests bring their own (MTP_CARRY_STARTUP=1): the UART, the heap (the
// µOS++ free store over the linker's heap region), the exception vectors,
// and the main thread that runs os_main (). The boot code (startup.S) clears
// .bss, calls os_startup_initialize_hardware () below, then
// __libc_init_array () -- the static constructors, which may therefore
// allocate -- then main ().
// GENERATED by micro-os-scaffold (--micro-test-plus); see README.md here.
//
// Include it once, at the end of a test's main.cpp. On the boards that
// provide the start-up themselves (MTP_CARRY_STARTUP=0) it is empty.
#pragma once

#if defined(MTP_CARRY_STARTUP) && MTP_CARRY_STARTUP

#include "mtp_semihosting.hpp"

#include <cmsis-plus/rtos/os.h>

#include <exception_handler.hpp>
#include <uart.hpp>

#include <cstdlib>

extern "C"
{
  extern char __heap_start[];
  extern char __heap_end[];
  extern char __fiq_stack_top[];
  extern char __irq_stack_top[];

  void os_startup_initialize_hardware_early (void) { }

  void
  os_startup_initialize_hardware (void)
  {
    uart::uart1.init ();
    os_startup_initialize_free_store (
        __heap_start, static_cast<std::size_t> (__heap_end - __heap_start));
    exception::init ();
  }

  // The command line the debugger/emulator passed, read before the main
  // thread starts (SYS_GET_CMDLINE must run on the core the debugger is
  // servicing; the boot core runs this).
  static int mtp_argc = 1;
  static char** mtp_argv = nullptr;

  [[noreturn]] static void
  mtp_main_trampoline (void)
  {
    std::exit (os_main (mtp_argc, mtp_argv));
  }

  extern void os_startup_create_thread_idle (void);
  extern os::rtos::thread* os_main_thread;

  int
  main (int argc, char* argv[])
  {
#if defined(MTP_SEMIHOST_ARGS) && MTP_SEMIHOST_ARGS == 2
    // AArch32/AArch64: the port's startup calls main() without arguments,
    // so the command line comes from the debugger/emulator.
    mtp_semihosting::args (mtp_argc, mtp_argv);
#else
    // Hosted: the process arguments are already here.
    mtp_argc = argc;
    mtp_argv = argv;
#endif
#if defined(OS_HAS_INTERRUPTS_STACK)
    os::rtos::interrupts::stack ()->set (
        reinterpret_cast<os::rtos::thread::stack::element_t*> (__fiq_stack_top),
        __irq_stack_top - __fiq_stack_top);
    os::rtos::interrupts::stack ()->initialize ();
#endif
    os::rtos::scheduler::initialize ();

    static os::rtos::thread::stack::element_t main_stack[32768];
    os::rtos::thread::attributes attr = os::rtos::thread::initializer;
    attr.th_stack_address = main_stack;
    attr.th_stack_size_bytes = sizeof (main_stack);
    static os::rtos::thread main_thread{
      "main", reinterpret_cast<os::rtos::thread::func_t> (mtp_main_trampoline),
      nullptr, attr
    };
    os_main_thread = &main_thread;

    os_startup_create_thread_idle ();
    os::rtos::scheduler::start ();
    return 0;
  }
}

#endif // MTP_CARRY_STARTUP
